import { cacheTag } from 'next/cache';

export type Post = {
  id: string;
  title: string;
};

const posts: Post[] = [
  { id: '1', title: 'First post' },
  { id: '2', title: 'Second post' }
];

export async function listPosts(): Promise<Post[]> {
  'use cache';
  cacheTag('posts');

  return posts;
}

export function createPost(title: string): Post {
  const post = { id: crypto.randomUUID(), title };
  posts.unshift(post);
  return post;
}

